\begin{aligned}[t]
      &\left(
        u\in\mathbb Z\land
        \exists a,b,c,d\in\mathbb N\,
        \left\{
        \begin{aligned}
          z&=\IntClass{a}{b},\\
          w&=\IntClass{c}{d},\\
          u&=\IntClass{a+c}{b+d}
        \end{aligned}
        \right.
      \right)\dsep{}\\
