        \left\{
        \begin{aligned}
          z&=\IntClass{a'}{b'},\\
          w&=\IntClass{c'}{d'},\\
          v&=\IntClass{a'+c'}{b'+d'}
        \end{aligned}
        \right.
      \right)
      \vdash u=v
    \end{aligned}

