        \end{aligned}
        \right.
    \end{aligned}

\begin{aligned}[t]
    &a,b,a',b',c,d,c',d'\in\mathbb N\dsep
      \IntClass{a}{b}=\IntClass{a'}{b'}\dsep
      \IntClass{c}{d}=\IntClass{c'}{d'}\vdash{}\\
    &\IntClass{a\cdot c+b\cdot d}{a\cdot d+b\cdot c}
      =
      \IntClass{a'\cdot c'+b'\cdot d'}{a'\cdot d'+b'\cdot c'}
  \end{aligned}

\begin{aligned}[t]
      &a,b,c,d,c',d'\in\mathbb N\dsep
      \IntClass{c}{d}=\IntClass{c'}{d'}\vdash{}\\
      &\IntClass{a c+b d}{a d+b c}
       =\IntClass{a c'+b d'}{a d'+b c'}
    \end{aligned}

\begin{aligned}[t]
      &a,b,c,d,a',b',c',d'\in\mathbb N\dsep{}\\
      &z=\IntClass{a}{b}\land w=\IntClass{c}{d}
        \land u=\IntClass{ac+bd}{ad+bc}\dsep{}\\
      &z=\IntClass{a'}{b'}\land w=\IntClass{c'}{d'}
        \land v=\IntClass{a'c'+b'd'}{a'd'+b'c'}
      \vdash u=v
    \end{aligned}

a,c\in\mathbb Z\dsep b,d\in\PositiveIntegers\vdash
  \bigl(\RatClass{a}{b}=\RatClass{c}{d}
  \leftrightarrow a\cdot d=c\cdot b\bigr)

q\in\mathbb Q\vdash
  \exists a\in\mathbb Z\,\exists b\in\PositiveIntegers\,
  q=\RatClass{a}{b}

\begin{aligned}[t]
    &a,a',c,c'\in\mathbb Z\dsep
      b,b',d,d'\in\PositiveIntegers\dsep
      \RatClass{a}{b}=\RatClass{a'}{b'}\dsep{}\\
    &\RatClass{c}{d}=\RatClass{c'}{d'}\vdash
      \RatClass{a\cdot d+c\cdot b}{b\cdot d}
      =\RatClass{a'\cdot d'+c'\cdot b'}{b'\cdot d'}
  \end{aligned}

a,c\in\mathbb Z\dsep b,d\in\PositiveIntegers\vdash
  \RatClass{a}{b}+\RatClass{c}{d}
  =\RatClass{a\cdot d+c\cdot b}{b\cdot d}

\begin{aligned}[t]
    &a,a',c,c'\in\mathbb Z\dsep
      b,b',d,d'\in\PositiveIntegers\dsep
      \RatClass{a}{b}=\RatClass{a'}{b'}\dsep{}\\
    &\RatClass{c}{d}=\RatClass{c'}{d'}\vdash
      \RatClass{a\cdot c}{b\cdot d}
      =\RatClass{a'\cdot c'}{b'\cdot d'}
  \end{aligned}

\begin{aligned}[t]
      &q,r\in\mathbb Q\vdash\exists u\in\mathbb Q\,{}\\
      &\exists a,c\in\mathbb Z\,\exists b,d\in\PositiveIntegers\,{}\\
      &\bigl(q=\RatClass{a}{b}\land r=\RatClass{c}{d}
        \land u=\RatClass{a c}{b d}\bigr)
    \end{aligned}

a,c\in\mathbb Z\dsep b,d\in\PositiveIntegers\vdash
  \bigl(\RatClass{a}{b}\leq\RatClass{c}{d}
  \leftrightarrow a\cdot d\leq c\cdot b\bigr)

